# 42 张 skill_* 与 ai/ 下全部提示词来源的整词匹配
import json, pathlib
prompts = {}
for f in ['ai/prompts.jsonl', 'ai/skill-book-prompts.jsonl',
          'ai/boss-concepts.jsonl', 'ai/dungeon-wave-concepts.jsonl']:
    for i, l in enumerate(pathlib.Path(f).read_text().splitlines(), 1):
        d = json.loads(l)
        prompts[f'{f}:{i}'] = d['prompt']
for p in sorted(pathlib.Path('ai/prompts').rglob('*.txt')):
    prompts[str(p)] = p.read_text()
print("prompt sources:", len(prompts))
skills = sorted(p.name[len('skill_'):-4] for p in pathlib.Path('assets/originalrpg/textures/item').glob('skill_*.png'))
hit = [s for s in skills if any(s in v for v in prompts.values())]
print("skill total:", len(skills))
print("whole-word hits:", len(hit), hit)
for s in hit:
    for k, v in prompts.items():
        if s in v:
            print("  ", s, "->", k, "|", [l for l in v.splitlines() if s in l][0][:90])

